## The Fixed Implementation

Here's the corrected code with proper synchronization:

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    ready     chan struct{} // Signals when loading completes
    err       error         // Stores load error for waiters
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data   map[string]*CacheEntry
    mu     sync.RWMutex
    ttl    time.Duration
    loader LoadFunc
    stats  Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Try read lock first for cache hit
    c.mu.RLock()
    entry, ok := c.data[key]
    if ok && entry.ready != nil {
        select {
        case <-entry.ready:
            // Entry is ready, check if valid
            if entry.err == nil && time.Now().Before(entry.ExpiresAt) {
                c.mu.RUnlock()
                atomic.AddInt64(&c.stats.Hits, 1)
                return entry.Value, nil
            }
        default:
            // Still loading, wait for it
            c.mu.RUnlock()
            return c.waitForLoad(ctx, entry)
        }
    }
    c.mu.RUnlock()

    // Need to load - acquire write lock
    c.mu.Lock()

    // Double-check after acquiring write lock
    if entry, ok := c.data[key]; ok && entry.ready != nil {
        select {
        case <-entry.ready:
            if entry.err == nil && time.Now().Before(entry.ExpiresAt) {
                c.mu.Unlock()
                atomic.AddInt64(&c.stats.Hits, 1)
                return entry.Value, nil
            }
        default:
            // Another goroutine is loading
            c.mu.Unlock()
            return c.waitForLoad(ctx, entry)
        }
    }

    // Create loading entry with channel
    entry = &CacheEntry{ready: make(chan struct{})}
    c.data[key] = entry
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    // Load outside lock
    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        entry.err = err
        delete(c.data, key)
    } else {
        entry.Value = value
        entry.ExpiresAt = time.Now().Add(c.ttl)
    }
    close(entry.ready) // Signal waiters
    c.mu.Unlock()

    if err != nil {
        return nil, err
    }
    return value, nil
}

func (c *Cache) waitForLoad(ctx context.Context, entry *CacheEntry) (interface{}, error) {
    select {
    case <-ctx.Done():
        return nil, ctx.Err()
    case <-entry.ready:
        if entry.err != nil {
            return nil, entry.err
        }
        return entry.Value, nil
    }
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    entry := &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
        ready:     make(chan struct{}),
    }
    close(entry.ready)
    c.data[key] = entry
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()
    for key, entry := range c.data {
        select {
        case <-entry.ready:
            if now.After(entry.ExpiresAt) {
                delete(c.data, key)
            }
        default:
            // Still loading, don't delete
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}
```

---

## Key Fixes Summary

| Issue | Fix |
|-------|-----|
| Unprotected map access | Use `sync.RWMutex` consistently |
| Stats races | Use `atomic.AddInt64` |
| Cache stampede | Channel-based signaling instead of busy-wait |
| GetMulti race | WaitGroup + mutex for results |
| cleanup race | Hold lock during entire cleanup |
| Loading coordination | Use closed channels to signal completion |

*taps console confidently*

The channel-based approach for load coordination is cleaner than the original busy-wait loop - no CPU waste spinning, proper error propagation to waiters, and no deadlock risk since we never hold locks while waiting on channels.

